add_action( 'init', 'perfectpixel_related_tab_setup' );
add_filter( 'woocommerce_product_tabs', 'perfectpixel_related_tab' );

function perfectpixel_related_tab_setup() {
	remove_action( 'woocommerce_after_single_product_summary', 'woocommerce_output_related_products', 20 );
}

function perfectpixel_related_tab( $tabs ) {
	global $product;
	if ( $product && wc_get_related_products( $product->get_id(), 1 ) ) {
		$tabs['perfectpixel_related'] = array(
			'title'    => '{{related_tab_title}}',
			'priority' => 40,
			'callback' => 'woocommerce_output_related_products',
		);
	}
	return $tabs;
}
